-- Additive Bondbuilder research storage. No backfill, no activation.
BEGIN;
DO $lineage$
BEGIN
 IF to_regprocedure('public.product_intake_bind_guidance_payload(jsonb,uuid)') IS NULL OR
 (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid='public.product_intake_approve_reviewed_product_before_thumbnail_image(uuid,jsonb,jsonb,text,timestamptz,text)'::regprocedure) IS DISTINCT FROM 'acac8a147af4eeb50d33921fe724aa64ff5a44df37d3c194f6c2ecba14b34c60'
 THEN RAISE EXCEPTION 'Bondbuilder requires reviewed September 29 protocol-binding repair'; END IF;
END $lineage$;
-- Frozen structural schema is generated from contracts.ts; semantic/hash checks follow.
CREATE OR REPLACE FUNCTION public.bondbuilder_json_canonical_v1(v jsonb)
RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
DECLARE result text; n numeric;
BEGIN
 CASE jsonb_typeof(v)
 WHEN 'object' THEN SELECT '{' || COALESCE(string_agg(to_jsonb(key)::text || ':' || public.bondbuilder_json_canonical_v1(value), ',' ORDER BY key COLLATE "C"), '') || '}' INTO result FROM jsonb_each(v);
 WHEN 'array' THEN SELECT '[' || COALESCE(string_agg(public.bondbuilder_json_canonical_v1(value), ',' ORDER BY ord), '') || ']' INTO result FROM jsonb_array_elements(v) WITH ORDINALITY AS a(value,ord);
 WHEN 'number' THEN
   n:=(v#>>'{}')::numeric;
   IF n=0 THEN result:='0';
   ELSIF abs(n)<0.000001 OR abs(n)>=1e21 THEN
     result:=regexp_replace((n::double precision)::text,'e(-?)0+','e\1','g');
   ELSIF n=trunc(n) THEN result:=trunc(n)::text;
   ELSE result:=regexp_replace(n::text,'0+$','');
   END IF;
 ELSE result := v::text;
 END CASE;
 RETURN result;
END $$;

