-- Deliberately restricted JSON-schema vocabulary used by the frozen profile.
CREATE OR REPLACE FUNCTION public.bondbuilder_shape_valid_v1(v jsonb, s jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
DECLARE item record; child jsonb; typ text := jsonb_typeof(v); n numeric; scalar text;
BEGIN
 IF v IS NULL THEN RETURN false; END IF;
 IF s ? 'anyOf' THEN
   FOR child IN SELECT value FROM jsonb_array_elements(s->'anyOf') LOOP
     IF public.bondbuilder_shape_valid_v1(v,child) THEN RETURN true; END IF;
   END LOOP;
   RETURN false;
 END IF;
 IF s ? 'oneOf' THEN
   SELECT count(*) INTO n FROM jsonb_array_elements(s->'oneOf') a WHERE public.bondbuilder_shape_valid_v1(v,a.value);
   RETURN n=1;
 END IF;
 IF s ? 'const' AND v IS DISTINCT FROM s->'const' THEN RETURN false; END IF;
 IF s ? 'enum' AND NOT (s->'enum' @> jsonb_build_array(v)) THEN RETURN false; END IF;
 IF s ? 'type' AND s->>'type' <> typ AND NOT(s->>'type'='integer' AND typ='number') THEN RETURN false; END IF;
 IF typ='object' THEN
   IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(COALESCE(s->'required','[]')) a WHERE NOT v ? a.value) THEN RETURN false; END IF;
   FOR item IN SELECT * FROM jsonb_each(v) LOOP
     IF NOT COALESCE(s->'properties','{}') ? item.key THEN
       IF s->>'additionalProperties'='false' THEN RETURN false; END IF;
     ELSIF NOT public.bondbuilder_shape_valid_v1(item.value,s->'properties'->item.key) THEN RETURN false;
     END IF;
   END LOOP;
 ELSIF typ='array' THEN
   n:=jsonb_array_length(v);
   IF n<COALESCE((s->>'minItems')::numeric,0) OR n>COALESCE((s->>'maxItems')::numeric,1000000) THEN RETURN false; END IF;
   FOR child IN SELECT value FROM jsonb_array_elements(v) LOOP
     IF s ? 'items' AND NOT public.bondbuilder_shape_valid_v1(child,s->'items') THEN RETURN false; END IF;
   END LOOP;
 ELSIF typ='string' THEN
   scalar:=v#>>'{}'; n:=char_length(scalar);
   IF n<COALESCE((s->>'minLength')::numeric,0) OR n>COALESCE((s->>'maxLength')::numeric,1000000) THEN RETURN false; END IF;
   IF s ? 'pattern' AND scalar !~ (s->>'pattern') THEN RETURN false; END IF;
   IF s->>'format'='uri' AND scalar !~ '^[A-Za-z][A-Za-z0-9+.-]*:' THEN RETURN false; END IF;
   IF s->>'format'='uuid' AND scalar !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN false; END IF;
 ELSIF typ='number' THEN
   n:=(v#>>'{}')::numeric;
   IF s->>'type'='integer' AND trunc(n)<>n THEN RETURN false; END IF;
   IF n<COALESCE((s->>'minimum')::numeric,n) OR n>COALESCE((s->>'maximum')::numeric,n) THEN RETURN false; END IF;
   IF s ? 'exclusiveMinimum' AND n<=(s->>'exclusiveMinimum')::numeric THEN RETURN false; END IF;
 END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION public.bondbuilder_normalize_inci_v1(raw text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
DECLARE i integer; depth integer:=0; c text; part text:=''; result jsonb:='[]'; clean text;
 -- Match ECMAScript \s/trim, including copied producer-page NBSP and BOM.
 whitespace text:=U&'[\0009-\000D\0020\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]';
BEGIN
 clean:=regexp_replace(raw,'<ILN[^>]*>'||whitespace||'*$','','i');
 clean:=regexp_replace(clean,'\(F\.I\.L\.[^)]*\)\.?'||whitespace||'*$','','i');
 clean:=regexp_replace(clean,'\(and\)',',','gi');
 clean:=regexp_replace(clean,'([0-9]),'||whitespace||'+(?=[0-9]-)','\1,','g');
 FOR i IN 1..char_length(clean) LOOP
   c:=substr(clean,i,1);
   IF c='(' THEN depth:=depth+1; ELSIF c=')' THEN depth:=depth-1; END IF;
   IF depth<0 THEN RETURN '[]'; END IF;
   IF depth=0 AND (c='•' OR (c=',' AND NOT (substr(clean,i-1,1) ~ '[0-9]' AND substr(clean,i+1,1) ~ '[0-9]'))) THEN
     part:=lower(btrim(regexp_replace(regexp_replace(part,'[*†]','','g'),whitespace||'+',' ','g')));
     IF part<>'' THEN result:=result || jsonb_build_array(part); END IF; part:='';
   ELSE part:=part||c; END IF;
 END LOOP;
 IF depth<>0 THEN RETURN '[]'; END IF;
 part:=lower(btrim(regexp_replace(regexp_replace(part,'[*†]','','g'),whitespace||'+',' ','g')));
 IF part<>'' THEN result:=result || jsonb_build_array(part); END IF;
 RETURN result;
END $$;

CREATE OR REPLACE FUNCTION public.bondbuilder_profile_digest_v1(p jsonb)
RETURNS text LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
 SELECT encode(sha256(convert_to(public.bondbuilder_json_canonical_v1(p #- '{method,output_sha256}' #- '{review,profile_sha256}'),'UTF8')),'hex')
$$;

CREATE OR REPLACE FUNCTION public.bondbuilder_semantics_valid_v1(v jsonb, sources jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
DECLARE item record; child jsonb; sid text;
BEGIN
 IF jsonb_typeof(v)='object' THEN
   IF v ? 'unknown_reason' THEN
     IF v->'value'='null'::jsonb THEN
       IF v->>'unknown_reason' IS NULL THEN RETURN false; END IF;
     ELSIF v->'unknown_reason'<>'null'::jsonb OR jsonb_array_length(v->'source_ids')=0 THEN RETURN false;
     END IF;
   END IF;
   IF v->>'kind'='range_seconds' AND (v->>'minimum_seconds')::numeric>(v->>'maximum_seconds')::numeric THEN RETURN false; END IF;
   IF v->>'kind' IN ('every_n_washes','times_per_week') AND (v->>'minimum')::numeric>(v->>'maximum')::numeric THEN RETURN false; END IF;
   FOR item IN SELECT * FROM jsonb_each(v) LOOP
     IF item.key LIKE '%source_ids' THEN
       IF (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements_text(item.value)) THEN RETURN false; END IF;
       FOR sid IN SELECT value FROM jsonb_array_elements_text(item.value) LOOP
         IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sources) s WHERE s.value->>'id'=sid AND s.value->>'access'<>'uninspected') THEN RETURN false; END IF;
       END LOOP;
     END IF;
     IF item.key IN ('checked_date','reviewed_date') AND item.value<>'null'::jsonb AND to_char((item.value#>>'{}')::date,'YYYY-MM-DD')<>item.value#>>'{}' THEN RETURN false; END IF;
     IF NOT public.bondbuilder_semantics_valid_v1(item.value,sources) THEN RETURN false; END IF;
   END LOOP;
 ELSIF jsonb_typeof(v)='array' THEN
   FOR child IN SELECT value FROM jsonb_array_elements(v) LOOP
     IF NOT public.bondbuilder_semantics_valid_v1(child,sources) THEN RETURN false; END IF;
   END LOOP;
 END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION public.bondbuilder_profile_valid_v1(p jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
DECLARE owner jsonb; ref jsonb; marker jsonb; pinned_formula jsonb; tokens jsonb; family text; lexicon jsonb;
BEGIN
 IF p IS NULL OR octet_length(convert_to(public.bondbuilder_json_canonical_v1(p),'UTF8'))>262144 OR NOT public.bondbuilder_shape_valid_v1(p,public.bondbuilder_profile_schema_v1()) THEN RETURN false; END IF;
 SELECT r.value->'normalized_ingredients' INTO pinned_formula FROM jsonb_array_elements(public.bondbuilder_owner_registry_v1()) r WHERE r.value->>'raw_sha256'=p#>>'{formula,raw_sha256}' AND r.value->>'normalized_sha256'=p#>>'{formula,normalized_sha256}';
 IF NOT EXISTS(
   SELECT 1 FROM jsonb_array_elements(public.bondbuilder_accepted_method_pins_v1()) accepted
   WHERE p->'method' @> accepted.value
 )
 OR p#>>'{identity,status}'<>'resolved'
 OR p#>>'{formula,status}'<>'complete'
 OR p#>>'{assessment,boundary_status}'<>'in_scope'
 OR p#>>'{assessment,technology_family}' IS NULL
 OR p#>>'{assessment,claim_trust_level}' IS NULL
 OR p#>>'{assessment,trust_basis}' IS NULL
 OR p#>>'{formula,raw_sha256}'<>encode(sha256(convert_to(p#>>'{formula,raw_inci}','UTF8')),'hex')
 OR p#>'{formula,normalized_ingredients}'<>COALESCE(pinned_formula,public.bondbuilder_normalize_inci_v1(p#>>'{formula,raw_inci}'))
 OR p#>>'{formula,normalized_sha256}'<>encode(sha256(convert_to(public.bondbuilder_json_canonical_v1(p#>'{formula,normalized_ingredients}'),'UTF8')),'hex')
 OR p#>>'{review,profile_sha256}'<>public.bondbuilder_profile_digest_v1(p)
 OR p#>>'{method,output_sha256}'<>public.bondbuilder_profile_digest_v1(p)
 OR NOT public.bondbuilder_semantics_valid_v1(p,p->'sources')
 OR (SELECT count(*)<>count(DISTINCT value->>'id') FROM jsonb_array_elements(p->'sources'))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p#>'{formula,conflicts}') c WHERE c.value->>'resolved'<>'true')
 OR jsonb_array_length(p#>'{holds,identity}')>0 OR jsonb_array_length(p#>'{holds,boundary}')>0 OR jsonb_array_length(p#>'{holds,claim_trust}')>0
 OR p#>>'{assessment,reasoning,boundary_status,confidence}'='low'
 OR p#>'{application,treatment_role,value}'='null'::jsonb
 OR jsonb_array_length(p#>'{assessment,reasoning,boundary_status,source_ids}')=0
 THEN RETURN false; END IF;
 SELECT r.value INTO owner FROM jsonb_array_elements(public.bondbuilder_owner_registry_v1()) r
 WHERE p->'identity' @> (r.value - ARRAY['research_key','source_url','raw_sha256','normalized_sha256','normalized_ingredients','technology_family','claim_trust_level','trust_basis','policy_reference'])
 AND p#>>'{formula,raw_sha256}'=r.value->>'raw_sha256'
 AND p#>>'{formula,normalized_sha256}'=r.value->>'normalized_sha256'
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(p->'sources') s WHERE s.value->>'url'=r.value->>'source_url' AND p#>'{formula,source_ids}' @> jsonb_build_array(s.value->>'id'));
 IF owner IS NOT NULL THEN
   IF p->'assessment' @> jsonb_build_object('technology_family',owner->>'technology_family','claim_trust_level',owner->>'claim_trust_level','trust_basis',owner->>'trust_basis','policy_reference',owner->>'policy_reference') IS NOT TRUE THEN RETURN false; END IF;
 ELSE
   IF p#>>'{assessment,claim_trust_level}'<>'low' OR p#>>'{assessment,trust_basis}'<>'owner_default' OR p#>>'{assessment,policy_reference}'<>'owner-default-policy-2026-10-01' THEN RETURN false; END IF;
 END IF;
 IF jsonb_array_length(p#>'{formula,markers}')=0 THEN RETURN false; END IF;
 tokens:=p#>'{formula,normalized_ingredients}'; family:=p#>>'{assessment,technology_family}';
 lexicon:='{"sulfur_targeting_dimaleate":["bis-aminopropyl diglycol dimaleate"],"designed_peptide":["sh-oligopeptide-78"],"maleate_ester":["diethylhexyl maleate"],"acid_calcium_management":["citric acid","sodium citrate","glycine","arginine","betaine"],"gluconamide_gluconate":["hydroxypropylgluconamide","hydroxypropylammonium gluconate"]}';
 IF NOT p#>'{formula,candidate_families}' @> jsonb_build_array(family)
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(tokens) t WHERE regexp_replace(t.value,'[[:space:]]','','g')=regexp_replace(lexicon#>>ARRAY[family,'0'],'[[:space:]]','','g'))
 OR (family='gluconamide_gluconate' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(tokens) t WHERE regexp_replace(t.value,'[[:space:]]','','g')='hydroxypropylammoniumgluconate')) THEN RETURN false; END IF;
 FOR marker IN SELECT value FROM jsonb_array_elements(p#>'{formula,markers}') LOOP
   IF NOT tokens @> jsonb_build_array(marker->>'literal') OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(lexicon->(marker->>'family')) m WHERE regexp_replace(m.value,'[[:space:]]','','g')=regexp_replace(marker->>'literal','[[:space:]]','','g')) THEN RETURN false; END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p#>'{formula,markers}') m WHERE m.value->>'family'=family) THEN RETURN false; END IF;
 IF p#>>'{technology_reference,status}'='matched' THEN
   SELECT r.value INTO ref FROM jsonb_array_elements(public.bondbuilder_owner_registry_v1()) r WHERE r.value->>'research_key'=p#>>'{technology_reference,research_key}' AND r.value->>'research_key' IN ('P01','P02','P03','P04','P06');
   IF ref IS NULL OR ref->>'normalized_sha256'<>p#>>'{technology_reference,formula_sha256}' OR ref->>'source_version'<>p#>>'{technology_reference,source_version}' OR ref->>'technology_family'<>p#>>'{assessment,technology_family}' OR jsonb_array_length(p#>'{technology_reference,shared_markers}')=0 OR jsonb_array_length(p#>'{technology_reference,source_ids}')=0 OR p#>>'{technology_reference,product_id}' IS NOT NULL
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(p#>'{technology_reference,shared_markers}') m WHERE NOT tokens @> jsonb_build_array(m.value) OR NOT ref->'normalized_ingredients' @> jsonb_build_array(m.value) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p#>'{formula,markers}') observed WHERE observed.value->'literal'=m.value AND observed.value->>'family'=family)) THEN RETURN false; END IF;
 ELSE
   IF p#>>'{technology_reference,research_key}' IS NOT NULL OR p#>>'{technology_reference,formula_sha256}' IS NOT NULL OR p#>>'{technology_reference,product_id}' IS NOT NULL OR p#>>'{technology_reference,source_version}' IS NOT NULL OR jsonb_array_length(p#>'{technology_reference,shared_markers}')>0 THEN RETURN false; END IF;
 END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

ALTER TABLE public.product_bondbuilder_specs
 ADD COLUMN technology_family text,
 ADD COLUMN claim_trust_level text,
 ADD COLUMN trust_basis text,
 ADD COLUMN research_profile jsonb,
 ALTER COLUMN bond_repair_intensity DROP NOT NULL,
 ALTER COLUMN application_mode DROP NOT NULL,
 ALTER COLUMN bond_repair_axis DROP NOT NULL,
 ALTER COLUMN treatment_mode DROP NOT NULL,
 ALTER COLUMN product_format DROP NOT NULL,
 ALTER COLUMN usage_protocol DROP NOT NULL;
ALTER TABLE public.product_bondbuilder_specs
 DROP CONSTRAINT IF EXISTS product_bondbuilder_specs_usage_protocol_check;
ALTER TABLE public.product_bondbuilder_specs ADD CONSTRAINT product_bondbuilder_specs_usage_protocol_check CHECK
 (usage_protocol IN ('olaplex_3plus','olaplex_0_booster','olaplex_3_legacy','k18_leave_in','epres_spray','verified_product_protocol'));
ALTER TABLE public.product_bondbuilder_specs ADD CONSTRAINT bondbuilder_research_contract_v1 CHECK (
 CASE WHEN research_profile IS NULL THEN
 technology_family IS NULL AND claim_trust_level IS NULL AND trust_basis IS NULL
 AND bond_repair_intensity IS NOT NULL AND application_mode IS NOT NULL AND bond_repair_axis IS NOT NULL
 AND treatment_mode IS NOT NULL AND product_format IS NOT NULL AND usage_protocol IS NOT NULL
 AND usage_protocol<>'verified_product_protocol'
 ELSE
 public.bondbuilder_profile_valid_v1(research_profile)
 AND technology_family IS NOT NULL AND claim_trust_level IS NOT NULL AND trust_basis IS NOT NULL
 AND technology_family=research_profile#>>'{assessment,technology_family}'
 AND claim_trust_level=research_profile#>>'{assessment,claim_trust_level}'
 AND trust_basis=research_profile#>>'{assessment,trust_basis}'
 AND research_profile#>>'{identity,product_id}' IS NOT NULL
 AND product_id::text=research_profile#>>'{identity,product_id}'
 END
);

CREATE OR REPLACE FUNCTION public.bondbuilder_bind_profile_v1(p jsonb, product_id uuid)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
DECLARE bound jsonb; digest text;
BEGIN
 IF NOT public.bondbuilder_profile_valid_v1(p) OR (p#>>'{identity,product_id}' IS NOT NULL AND p#>>'{identity,product_id}'<>product_id::text) THEN RAISE EXCEPTION 'invalid Bondbuilder profile or product identity'; END IF;
 bound:=jsonb_set(p,'{identity,product_id}',to_jsonb(product_id::text),false);
 digest:=public.bondbuilder_profile_digest_v1(bound);
 RETURN jsonb_set(jsonb_set(bound,'{method,output_sha256}',to_jsonb(digest),false),'{review,profile_sha256}',to_jsonb(digest),false);
END $$;

-- One explicit owned-field upsert; omitted legacy values remain unchanged,
-- whereas a present JSON null is an intentional correction subject to CHECK.
CREATE OR REPLACE FUNCTION public.bondbuilder_write_spec_v1(p_product_id uuid, p_row jsonb)
RETURNS void LANGUAGE plpgsql SET search_path = '' AS $$
DECLARE merged jsonb; profile jsonb; current_row jsonb; product public.products%ROWTYPE;
BEGIN
 IF jsonb_typeof(p_row)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_row) k WHERE k NOT IN ('product_id','bond_repair_intensity','application_mode','bond_repair_axis','treatment_mode','product_format','usage_protocol','technology_family','claim_trust_level','trust_basis','research_profile')) THEN RAISE EXCEPTION 'unsupported Bondbuilder owned field'; END IF;
 SELECT * INTO product FROM public.products WHERE id=p_product_id FOR UPDATE;
 SELECT to_jsonb(s) INTO current_row FROM public.product_bondbuilder_specs s WHERE s.product_id=p_product_id FOR UPDATE;
 merged:=COALESCE(current_row,'{}')||p_row;
 IF p_row ? 'research_profile' AND p_row->'research_profile'<>'null'::jsonb THEN
   profile:=public.bondbuilder_bind_profile_v1(p_row->'research_profile',p_product_id);
   IF profile#>>'{identity,product_name}'<>product.name OR profile#>>'{identity,brand}' IS DISTINCT FROM product.brand OR product.category_key<>'bondbuilder' THEN RAISE EXCEPTION 'Bondbuilder profile catalogue identity mismatch'; END IF;
   merged:=jsonb_set(merged,'{research_profile}',profile);
 END IF;
 INSERT INTO public.product_bondbuilder_specs(product_id,bond_repair_intensity,application_mode,bond_repair_axis,treatment_mode,product_format,usage_protocol,technology_family,claim_trust_level,trust_basis,research_profile)
 VALUES(p_product_id,merged->>'bond_repair_intensity',merged->>'application_mode',merged->>'bond_repair_axis',merged->>'treatment_mode',merged->>'product_format',merged->>'usage_protocol',merged->>'technology_family',merged->>'claim_trust_level',merged->>'trust_basis',NULLIF(merged->'research_profile','null'::jsonb))
 ON CONFLICT(product_id) DO UPDATE SET bond_repair_intensity=EXCLUDED.bond_repair_intensity,application_mode=EXCLUDED.application_mode,bond_repair_axis=EXCLUDED.bond_repair_axis,treatment_mode=EXCLUDED.treatment_mode,product_format=EXCLUDED.product_format,usage_protocol=EXCLUDED.usage_protocol,technology_family=EXCLUDED.technology_family,claim_trust_level=EXCLUDED.claim_trust_level,trust_basis=EXCLUDED.trust_basis,research_profile=EXCLUDED.research_profile,updated_at=now();
END $$;

-- Replace only the original Bondbuilder branch in its effective renamed owner.
-- Fail closed on any unexpected installed body; do not replace repaired wrappers.
DO $writer$
DECLARE body text; replacement text; start_at integer; end_at integer;
BEGIN
 SELECT prosrc INTO body FROM pg_proc WHERE oid='public.product_intake_approve_reviewed_product_legacy(uuid,jsonb,jsonb,text,timestamptz,text)'::regprocedure;
 IF encode(sha256(convert_to(body,'UTF8')),'hex') <> '3f4377bc582da4aabe4ff2b4b7037fc58a1d26c0b96aef33532deea93abc980c' THEN RAISE EXCEPTION 'Bondbuilder legacy writer digest changed'; END IF;
 start_at:=strpos(body,'    ELSIF operation_table = ''product_bondbuilder_specs'' THEN');
 end_at:=strpos(substr(body,start_at),E'    ELSE\n      RAISE EXCEPTION ''unsupported product intake spec operation table:');
 IF start_at=0 OR end_at=0 THEN RAISE EXCEPTION 'Bondbuilder legacy writer lineage changed'; END IF;
 replacement:=E'    ELSIF operation_table = ''product_bondbuilder_specs'' THEN\n      IF jsonb_array_length(operation->''rows'') <> 1 THEN RAISE EXCEPTION ''one Bondbuilder spec row required''; END IF;\n      PERFORM public.bondbuilder_write_spec_v1(new_product_id, operation->''rows''->0);\n';
 body:=substr(body,1,start_at-1)||replacement||substr(body,start_at+end_at-1);
 EXECUTE format('CREATE OR REPLACE FUNCTION public.product_intake_approve_reviewed_product_legacy(p_submission_id uuid,p_final_payload jsonb,p_spec_operations jsonb,p_reviewed_by text,p_reviewed_at timestamptz DEFAULT now(),p_review_notes text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public AS %L',body);
END $writer$;

-- The snapshot is both a reviewable preimage and a replay readback oracle.
CREATE OR REPLACE FUNCTION public.bondbuilder_research_preimage_v1(p_product_id uuid)
RETURNS jsonb LANGUAGE sql STABLE SET search_path = '' AS $$
 SELECT jsonb_build_object(
 'product',to_jsonb(p),
 'specs',(SELECT to_jsonb(s) FROM public.product_bondbuilder_specs s WHERE s.product_id=p.id),
 'protocols',COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.category,a.role,a.application_family) FROM public.product_application_protocols a WHERE a.product_id=p.id),'[]'::jsonb))
 FROM public.products p WHERE p.id=p_product_id
$$;
CREATE OR REPLACE FUNCTION public.bondbuilder_research_protected_v1(p_preimage jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
 SELECT jsonb_set(p_preimage,'{specs}',jsonb_build_object('product_id',p_preimage#>>'{product,id}','bond_repair_intensity',p_preimage#>'{specs,bond_repair_intensity}','application_mode',p_preimage#>'{specs,application_mode}','bond_repair_axis',p_preimage#>'{specs,bond_repair_axis}','treatment_mode',p_preimage#>'{specs,treatment_mode}','product_format',p_preimage#>'{specs,product_format}','usage_protocol',p_preimage#>'{specs,usage_protocol}'))
$$;

-- Extends the existing evidence + applied-item ledger, not a second catalogue.
CREATE OR REPLACE FUNCTION public.bondbuilder_research_enrich_v1(
 p_product_id uuid,p_profile jsonb,p_expected_preimage jsonb,p_request_id uuid,p_reviewed_by text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE current_image jsonb; bound jsonb; protected_image jsonb; batch text:='bondbuilder-research-v1:'||p_request_id::text;
 fingerprint text; content text; prior public.catalog_enrichment_applied_items%ROWTYPE; evidence jsonb; src jsonb;
BEGIN
 IF p_request_id IS NULL OR NULLIF(btrim(p_reviewed_by),'') IS NULL OR p_expected_preimage IS NULL THEN RAISE EXCEPTION 'reviewed Bondbuilder preimage and request required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('catalog-enrichment:product-apply',0));
 PERFORM pg_advisory_xact_lock(hashtextextended(batch,0));
 PERFORM 1 FROM public.products WHERE id=p_product_id FOR UPDATE;
 PERFORM 1 FROM public.product_bondbuilder_specs WHERE product_id=p_product_id FOR UPDATE;
 PERFORM 1 FROM public.product_application_protocols WHERE product_id=p_product_id FOR UPDATE;
 current_image:=public.bondbuilder_research_preimage_v1(p_product_id);
 IF current_image IS NULL OR current_image#>>'{product,category_key}'<>'bondbuilder' THEN RAISE EXCEPTION 'Bondbuilder product not found'; END IF;
 bound:=public.bondbuilder_bind_profile_v1(p_profile,p_product_id);
 fingerprint:=encode(sha256(convert_to(public.bondbuilder_json_canonical_v1(jsonb_build_object('preimage',p_expected_preimage,'profile',p_profile)),'UTF8')),'hex');
 content:=bound#>>'{review,profile_sha256}';
 SELECT * INTO prior FROM public.catalog_enrichment_applied_items WHERE batch_id=batch AND product_key=p_product_id::text;
 IF FOUND THEN
   SELECT fact_value INTO evidence FROM public.personal_plan_catalog_fact_evidence WHERE product_id=p_product_id AND fact_key='bondbuilder_research_preserved_bundle' AND batch_id=batch;
   IF prior.batch_fingerprint<>fingerprint OR prior.content_fingerprint<>content OR prior.product_id<>p_product_id
      OR current_image#>'{specs,research_profile}' IS DISTINCT FROM bound
      OR public.bondbuilder_research_protected_v1(current_image) IS DISTINCT FROM evidence
      OR (SELECT count(*) FROM public.personal_plan_catalog_fact_evidence e WHERE e.product_id=p_product_id AND e.fact_key IN ('bondbuilder_research_profile','bondbuilder_research_preserved_bundle'))<>2
      OR NOT EXISTS(SELECT 1 FROM public.personal_plan_catalog_fact_evidence e WHERE e.product_id=p_product_id AND e.fact_key='bondbuilder_research_profile' AND e.fact_value=bound AND e.batch_id=batch AND e.batch_fingerprint=fingerprint AND e.content_fingerprint=content AND e.source_text=bound#>>'{evidence,summary}' AND e.checked_at=(bound#>>'{review,checked_date}')::date AND EXISTS(SELECT 1 FROM jsonb_array_elements(bound->'sources') s WHERE s.value->>'url'=e.source_url AND bound#>'{formula,source_ids}' @> jsonb_build_array(s.value->>'id')))
      THEN RAISE EXCEPTION 'Bondbuilder replay drift'; END IF;
   RETURN jsonb_build_object('outcome','already_applied','product_id',p_product_id,'profile_sha256',content);
 END IF;
 IF current_image IS DISTINCT FROM p_expected_preimage THEN RAISE EXCEPTION 'Bondbuilder reviewed preimage changed'; END IF;
 -- Verify the original approved package before granting preservation authority.
 PERFORM public.assert_personal_plan_curated_publication(p_product_id);
 protected_image:=public.bondbuilder_research_protected_v1(current_image);
 PERFORM public.bondbuilder_write_spec_v1(p_product_id,jsonb_build_object('technology_family',bound#>>'{assessment,technology_family}','claim_trust_level',bound#>>'{assessment,claim_trust_level}','trust_basis',bound#>>'{assessment,trust_basis}','research_profile',bound));
 SELECT s.value INTO src FROM jsonb_array_elements(bound->'sources') s WHERE bound#>'{formula,source_ids}' @> jsonb_build_array(s.value->>'id') LIMIT 1;
 DELETE FROM public.personal_plan_catalog_fact_evidence WHERE product_id=p_product_id AND fact_key IN ('bondbuilder_research_profile','bondbuilder_research_preserved_bundle');
 INSERT INTO public.personal_plan_catalog_fact_evidence(product_id,fact_key,fact_value,source_label,source_url,source_text,source_type,checked_at,batch_id,batch_fingerprint,content_fingerprint)
 VALUES(p_product_id,'bondbuilder_research_profile',bound,'Reviewed Bondbuilder research',src->>'url',bound#>>'{evidence,summary}','internal_verified',(bound#>>'{review,checked_date}')::date,batch,fingerprint,content),
 (p_product_id,'bondbuilder_research_preserved_bundle',protected_image,'Reviewed existing product preimage',src->>'url','Research-only enrichment preserves this exact previously verified bundle.','internal_verified',(bound#>>'{review,checked_date}')::date,batch,fingerprint,content);
 INSERT INTO public.catalog_enrichment_applied_items(batch_id,product_key,batch_fingerprint,content_fingerprint,product_id,reviewed_by)
 VALUES(batch,p_product_id::text,fingerprint,content,p_product_id,p_reviewed_by);
 IF public.bondbuilder_research_protected_v1(public.bondbuilder_research_preimage_v1(p_product_id)) IS DISTINCT FROM protected_image THEN RAISE EXCEPTION 'Bondbuilder protected bundle changed'; END IF;
 PERFORM public.assert_personal_plan_curated_publication(p_product_id);
 RETURN jsonb_build_object('outcome','applied','product_id',p_product_id,'profile_sha256',content);
END $$;

CREATE OR REPLACE FUNCTION public.bondbuilder_curated_facts_ready_v1(p_product_id uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SET search_path = '' AS $$
DECLARE profile jsonb; product public.products%ROWTYPE; saved jsonb;
BEGIN
 SELECT research_profile INTO profile FROM public.product_bondbuilder_specs WHERE product_id=p_product_id;
 IF profile IS NULL THEN
  RETURN EXISTS(SELECT 1 FROM public.product_bondbuilder_specs WHERE product_id=p_product_id AND application_mode IS NOT NULL AND treatment_mode IS NOT NULL AND product_format IS NOT NULL AND usage_protocol IS NOT NULL);
 END IF;
 SELECT * INTO product FROM public.products WHERE id=p_product_id;
 -- A preserved preimage is authority only for the identical pre-existing package.
 SELECT e.fact_value INTO saved FROM public.personal_plan_catalog_fact_evidence e
 JOIN public.catalog_enrichment_applied_items l ON l.batch_id=e.batch_id AND l.product_key=p_product_id::text
 WHERE e.product_id=p_product_id AND e.fact_key='bondbuilder_research_preserved_bundle'
 AND e.content_fingerprint=profile#>>'{review,profile_sha256}' AND l.content_fingerprint=e.content_fingerprint
 AND l.batch_fingerprint=e.batch_fingerprint
 AND EXISTS(SELECT 1 FROM public.personal_plan_catalog_fact_evidence profile_evidence WHERE profile_evidence.product_id=p_product_id AND profile_evidence.fact_key='bondbuilder_research_profile' AND profile_evidence.fact_value=profile AND profile_evidence.batch_id=e.batch_id AND profile_evidence.batch_fingerprint=e.batch_fingerprint AND profile_evidence.content_fingerprint=e.content_fingerprint);
 IF saved IS NOT NULL AND public.bondbuilder_research_protected_v1(public.bondbuilder_research_preimage_v1(p_product_id))=saved
 AND ((saved#>>'{product,origin}'='curated' AND saved#>>'{product,is_active}'='true' AND saved#>>'{product,lifecycle_status}'='active') OR saved#>>'{product,is_chaarlie_recommended}'='true') THEN RETURN true; END IF;
 IF profile#>>'{assessment,claim_trust_level}' NOT IN ('medium','high') OR profile#>>'{assessment,trust_basis}' NOT IN ('owner_anchor','owner_calibration')
 OR profile#>>'{application,market_applicability}'<>'exact_market'
 OR jsonb_array_length(profile#>'{holds,protocol}')>0 OR jsonb_array_length(profile#>'{holds,fit}')>0
 OR cardinality(product.suitable_thicknesses)=0
 OR EXISTS(SELECT 1 FROM unnest(product.suitable_thicknesses) thickness WHERE thickness NOT IN ('fine','normal','coarse') OR profile#>>ARRAY['fit',thickness,'value'] IS DISTINCT FROM 'true')
 THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.product_application_protocols a
 WHERE a.product_id=p_product_id AND a.category='bondbuilder' AND a.role='specialized_bond_treatment'
 AND a.guidance_payload#>>'{scope,productId}'=p_product_id::text
 AND a.guidance_payload_v2#>>'{scope,productId}'=p_product_id::text
 AND a.guidance_payload_v2->'runtimeBlockerCode'='null'::jsonb
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(profile->'sources') s WHERE s.value->>'url'=a.source_url AND profile#>'{application,direction_source_ids}' @> jsonb_build_array(s.value->>'id') AND s.value->>'scope'='product' AND s.value->>'authority' IN ('pack','manufacturer','distributor','retailer') AND a.source_text=s.value->>'observation'));
END $$;

DO $publication$
DECLARE body text; old text:=E'WHEN ''bondbuilder'' THEN EXISTS (SELECT 1 FROM public.product_bondbuilder_specs bb WHERE bb.product_id = v_product.id\n      AND bb.application_mode IS NOT NULL AND bb.treatment_mode IS NOT NULL\n      AND bb.product_format IS NOT NULL AND bb.usage_protocol IS NOT NULL)';
BEGIN
 SELECT prosrc INTO body FROM pg_proc WHERE oid='public.assert_personal_plan_curated_publication_v1_without_v2(uuid)'::regprocedure;
 -- Accept only the original repository guard or the byte-exact deployed guard
 -- from 20260812102000 (scalp-care thickness applicability). Preserve its other arms.
 IF encode(sha256(convert_to(body,'UTF8')),'hex') NOT IN ('cd57f65d964529ac154def1ad628cad7badb7192de79b33a7815e0e1b456eb62','a3f7c5bf541a992a3b97ef8aa45714f0e7786e1643492b23c9d0bf3975840914') OR strpos(body,old)=0 THEN RAISE EXCEPTION 'Bondbuilder curated assertion lineage changed'; END IF;
 body:=replace(body,old,'WHEN ''bondbuilder'' THEN public.bondbuilder_curated_facts_ready_v1(v_product.id)');
 body:=replace(body,E'  IF EXISTS (\n    SELECT 1\n    FROM public.personal_plan_product_search_dispositions disposition',E'  IF v_product.category_key = ''bondbuilder'' AND EXISTS (SELECT 1 FROM public.product_bondbuilder_specs WHERE product_id=v_product.id AND research_profile IS NOT NULL) AND NOT public.bondbuilder_curated_facts_ready_v1(v_product.id) THEN\n    RAISE EXCEPTION ''curated publication requires reviewed Bondbuilder facts, fit and exact source-bound protocol'';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1\n    FROM public.personal_plan_product_search_dispositions disposition');
 EXECUTE format('CREATE OR REPLACE FUNCTION public.assert_personal_plan_curated_publication_v1_without_v2(p_product_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '''' AS %L',body);
END $publication$;

-- Dedicated server-owned ABI; never selected by a field inside an LLM profile.
-- The ordinary outer ABI continues to require executable V1/V2 and null blocker.
CREATE OR REPLACE FUNCTION public.product_intake_approve_bondbuilder_owner_v1(
 p_submission_id uuid,p_owner_user_id uuid,p_final_payload jsonb,p_spec_operations jsonb,p_reviewed_by text,
 p_reviewed_at timestamptz DEFAULT now(),p_review_notes text DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE submission public.product_submissions%ROWTYPE; row jsonb; payload jsonb:=p_final_payload;
profile jsonb; result jsonb; v_product_id uuid; image text; image_hash text; thumbnail text;
BEGIN
 SELECT * INTO submission FROM public.product_submissions WHERE id=p_submission_id FOR UPDATE;
 IF submission.id IS NULL OR submission.user_id IS DISTINCT FROM p_owner_user_id OR submission.source NOT IN ('chat','onboarding','personal_plan') OR submission.category<>'bondbuilder' OR submission.status<>'ready_for_review' OR p_owner_user_id IS NULL OR NULLIF(btrim(p_reviewed_by),'') IS NULL THEN RAISE EXCEPTION 'owner-scoped Bondbuilder submission required'; END IF;
 IF jsonb_typeof(p_spec_operations) IS DISTINCT FROM 'array' OR jsonb_array_length(p_spec_operations)<>1 OR p_spec_operations#>>'{0,table}'<>'product_bondbuilder_specs' OR jsonb_array_length(p_spec_operations#>'{0,rows}')<>1 THEN RAISE EXCEPTION 'owner Bondbuilder path permits only one research spec'; END IF;
 row:=p_spec_operations#>'{0,rows,0}'; profile:=row->'research_profile';
 IF NOT public.bondbuilder_profile_valid_v1(profile)
 OR profile#>>'{assessment,claim_trust_level}'<>'low' OR profile#>>'{assessment,trust_basis}'<>'owner_default'
 OR row->>'usage_protocol' IS NOT NULL
 OR p_final_payload#>>'{product,category_key}' IS DISTINCT FROM 'bondbuilder'
 OR p_final_payload#>>'{product,canonical_brand}' IS DISTINCT FROM profile#>>'{identity,brand}'
 OR concat_ws(' ',p_final_payload#>>'{product,canonical_brand}',NULLIF(p_final_payload#>>'{product,product_line}',''),p_final_payload#>>'{product,clean_name}') IS DISTINCT FROM profile#>>'{identity,product_name}'
 THEN RAISE EXCEPTION 'owner Bondbuilder path requires exact low default research without executable selector'; END IF;
 image:=NULLIF(payload#>>'{product,image_url}',''); image_hash:=NULLIF(payload#>>'{product,canonical_image_sha256}',''); thumbnail:=NULLIF(payload#>>'{product,thumbnail_image_url}','');
 IF image IS NULL AND (image_hash IS NOT NULL OR thumbnail IS NOT NULL) THEN RAISE EXCEPTION 'thumbnail metadata requires a canonical product image'; END IF;
 IF image IS NOT NULL AND image !~ '^https://pqdkhefxsxkyeqelqegq[.]supabase[.]co/storage/v1/object/public/product-images/.+' THEN RAISE EXCEPTION 'canonical product image must be stored in Chaarlie bucket'; END IF;
 IF (image_hash IS NOT NULL OR thumbnail IS NOT NULL) AND (image_hash IS NULL OR image_hash !~ '^[a-f0-9]{64}$' OR thumbnail IS DISTINCT FROM 'https://pqdkhefxsxkyeqelqegq.supabase.co/storage/v1/object/public/product-images/thumbnails/search-v1/'||image_hash||'.webp') THEN RAISE EXCEPTION 'thumbnail source hash mismatch'; END IF;
 IF submission.scanned_identifier_type IS NOT NULL AND submission.scanned_identifier_value IS NOT NULL THEN
 payload:=jsonb_set(payload,'{identifiers}',COALESCE(payload->'identifiers','[]')||jsonb_build_array(jsonb_build_object('type',submission.scanned_identifier_type,'value',submission.scanned_identifier_value,'source','scan')),true);
 END IF;
 payload:=public.product_identifier_prepare_final_payload_identifiers(payload,NULL);
 result:=public.product_intake_approve_reviewed_product_without_canonical_guidance(p_submission_id,payload,p_spec_operations,p_reviewed_by,p_reviewed_at,p_review_notes);
 v_product_id:=(result->>'product_id')::uuid;
 UPDATE public.products SET thumbnail_image_url=thumbnail,net_content_value=NULLIF(payload#>>'{product,net_content_value}','')::numeric,net_content_unit=NULLIF(payload#>>'{product,net_content_unit}','') WHERE id=v_product_id;
 IF NOT EXISTS(SELECT 1 FROM public.products p WHERE p.id=v_product_id AND p.origin='user_submitted' AND NOT p.is_chaarlie_recommended AND cardinality(p.suitable_thicknesses)=0) OR EXISTS(SELECT 1 FROM public.product_application_protocols a WHERE a.product_id=v_product_id) THEN RAISE EXCEPTION 'owner Bondbuilder isolation failed'; END IF;
 RETURN result;
END $$;

-- Explicit least privilege for every new callable helper and both service APIs.
CREATE OR REPLACE FUNCTION public.bondbuilder_validate_bound_row_v1()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE target uuid; targets uuid[]; profile jsonb; selector text; product public.products%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='products' THEN targets:=ARRAY[NEW.id];
 ELSIF TG_OP='UPDATE' THEN targets:=ARRAY[OLD.product_id,NEW.product_id];
 ELSIF TG_OP='DELETE' THEN targets:=ARRAY[OLD.product_id];
 ELSE targets:=ARRAY[NEW.product_id]; END IF;
 FOR target IN SELECT DISTINCT value FROM unnest(targets) value LOOP
 SELECT * INTO product FROM public.products WHERE id=target;
 SELECT research_profile,usage_protocol INTO profile,selector FROM public.product_bondbuilder_specs WHERE product_id=target;
 IF profile IS NULL THEN CONTINUE; END IF;
 IF profile#>>'{identity,product_name}' IS DISTINCT FROM product.name OR profile#>>'{identity,brand}' IS DISTINCT FROM product.brand OR product.category_key IS DISTINCT FROM 'bondbuilder' THEN RAISE EXCEPTION 'Bondbuilder profile catalogue identity mismatch'; END IF;
 IF profile#>>'{identity,gtin}' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.product_identifiers i WHERE i.product_id=target AND i.canonical_gtin14=public.product_identifier_canonical_gtin14('gtin',profile#>>'{identity,gtin}')) THEN RAISE EXCEPTION 'Bondbuilder profile GTIN is not bound to the product'; END IF;
 IF selector='verified_product_protocol' AND NOT EXISTS(
 SELECT 1 FROM public.product_application_protocols a WHERE a.product_id=target AND a.category='bondbuilder' AND a.role='specialized_bond_treatment'
 AND a.guidance_payload#>>'{scope,productId}'=target::text AND a.guidance_payload_v2#>>'{scope,productId}'=target::text AND a.guidance_payload_v2->'runtimeBlockerCode'='null'::jsonb
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(profile->'sources') s WHERE s.value->>'url'=a.source_url AND s.value->>'observation'=a.source_text AND profile#>'{application,direction_source_ids}' @> jsonb_build_array(s.value->>'id')))
 THEN RAISE EXCEPTION 'verified Bondbuilder selector requires exact executable source-bound protocol'; END IF;
 END LOOP;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER bondbuilder_validate_bound_spec_v1 AFTER INSERT OR UPDATE ON public.product_bondbuilder_specs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.bondbuilder_validate_bound_row_v1();
CREATE CONSTRAINT TRIGGER bondbuilder_validate_bound_product_v1 AFTER UPDATE OF name,brand,category_key ON public.products DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.bondbuilder_validate_bound_row_v1();
CREATE CONSTRAINT TRIGGER bondbuilder_validate_bound_identifier_v1 AFTER INSERT OR UPDATE OR DELETE ON public.product_identifiers DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.bondbuilder_validate_bound_row_v1();
CREATE CONSTRAINT TRIGGER bondbuilder_validate_bound_protocol_v1 AFTER INSERT OR UPDATE OR DELETE ON public.product_application_protocols DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.bondbuilder_validate_bound_row_v1();

DO $privileges$
DECLARE fn regprocedure;
BEGIN
 FOR fn IN SELECT oid::regprocedure FROM pg_proc WHERE pronamespace='public'::regnamespace AND (proname LIKE 'bondbuilder_%_v1' OR proname='product_intake_approve_bondbuilder_owner_v1') LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated, service_role',fn);
 END LOOP;
END $privileges$;
GRANT EXECUTE ON FUNCTION public.bondbuilder_research_preimage_v1(uuid),public.bondbuilder_research_enrich_v1(uuid,jsonb,jsonb,uuid,text),public.product_intake_approve_bondbuilder_owner_v1(uuid,uuid,jsonb,jsonb,text,timestamptz,text) TO service_role;
COMMIT;
